macro_rules! deps {
    () => {
        CompletionItemKind!();
        Builder!();
        CompletionRelevance!();
        CompletionItem!();
        CompletionContext!();
    };
}

macro_rules! render_expr {
    () => {
        deps!();
        pub (crate) fn render_expr (ctx : & CompletionContext < '_ > , expr : & hir :: term_search :: Expr < '_ > ,) -> Option < Builder > { let mut i = 1 ; let mut snippet_formatter = | ty : & hir :: Type < '_ > | { let arg_name = ty . as_adt () . map (| adt | stdx :: to_lower_snake_case (adt . name (ctx . db) . as_str ())) . unwrap_or_else (| | String :: from ("_")) ; let res = format ! ("${{{i}:{arg_name}}}") ; i += 1 ; res } ; let mut label_formatter = | ty : & hir :: Type < '_ > | { ty . as_adt () . map (| adt | stdx :: to_lower_snake_case (adt . name (ctx . db) . as_str ())) . unwrap_or_else (| | String :: from ("...")) } ; let cfg = ctx . config . find_path_config (ctx . is_nightly) ; let label = expr . gen_source_code (& ctx . scope , & mut label_formatter , cfg , ctx . display_target) . ok () ? ; let source_range = match ctx . original_token . parent () { Some (node) => match node . ancestors () . find_map (ast :: Path :: cast) { Some (path) => path . syntax () . text_range () , None => node . text_range () , } , None => ctx . source_range () , } ; let mut item = CompletionItem :: new (CompletionItemKind :: Expression , source_range , label , ctx . edition) ; let snippet = format ! ("{}$0" , expr . gen_source_code (& ctx . scope , & mut snippet_formatter , cfg , ctx . display_target) . ok () ?) ; let edit = TextEdit :: replace (source_range , snippet) ; item . snippet_edit (ctx . config . snippet_cap ? , edit) ; item . documentation (Documentation :: new (String :: from ("Autogenerated expression by term search"))) ; item . set_relevance (crate :: CompletionRelevance { type_match : compute_type_match (ctx , & expr . ty (ctx . db)) , .. Default :: default () }) ; for trait_ in expr . traits_used (ctx . db) { let trait_item = hir :: ItemInNs :: from (hir :: ModuleDef :: from (trait_)) ; let Some (path) = ctx . module . find_path (ctx . db , trait_item , cfg) else { continue ; } ; item . add_import (LocatedImport :: new_no_completion (path , trait_item , trait_item)) ; } Some (item) }
    };
}

render_expr!()